<?php
require_once __DIR__.'/../config/auth.php';check_access([1,2]);
require_once __DIR__.'/rapor_ranking.php';require_once __DIR__.'/rapor_tools.php';
$db=Database::getInstance();$ready=rapor_ready($db);$error='';$ranking=null;
$classes=$db->query('SELECT id,nama_kelas FROM kelas ORDER BY nama_kelas')->fetchAll();
$years=$db->query('SELECT DISTINCT tahun_ajaran FROM pengajaran ORDER BY tahun_ajaran DESC')->fetchAll(PDO::FETCH_COLUMN);
if($ready)$years=array_values(array_unique(array_merge($years,$db->query('SELECT DISTINCT tahun_ajaran FROM rapor ORDER BY tahun_ajaran DESC')->fetchAll(PDO::FETCH_COLUMN))));rsort($years);
$kelas=filter_var($_GET['kelas_id']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>0]])?:0;
$tahun=is_string($_GET['tahun_ajaran']??null)?$_GET['tahun_ajaran']:($years[0]??'');$semester=($_GET['semester']??'')==='Genap'?'Genap':'Ganjil';$jenis=($_GET['jenis']??'')==='UAS'?'UAS':'UTS';$all=($_GET['tampilan']??'')==='semua';
$selected=null;foreach($classes as $c)if((int)$c['id']===$kelas)$selected=$c;
if($kelas&&!$selected)$error='Kelas tidak ditemukan. Pilih kelas yang tersedia.';
elseif($selected&&$ready)try{$ranking=rapor_ranking_load($db,$kelas,$tahun,$semester,$jenis);}catch(InvalidArgumentException $e){$error=$e->getMessage();}catch(Throwable $e){error_log('Laporan peringkat rapor: '.$e->getMessage());$error='Laporan peringkat belum dapat dimuat. Silakan coba kembali.';}
$context=['kelas_id'=>$kelas,'tahun_ajaran'=>$tahun,'semester'=>$semester,'jenis'=>$jenis];
$shown=$ranking?array_values(array_filter($ranking['entries'],static fn(array $entry):bool=>$all||($entry['peringkat']!==null&&$entry['peringkat']<=10))):[];
$excluded=$ranking?array_values(array_filter($ranking['entries'],static fn(array $entry):bool=>$entry['peringkat']===null)):[];
require __DIR__.'/header.php';require __DIR__.'/sidebar.php';
?>
<link rel="stylesheet" href="../assets/css/rapor-form.css?v=12"><link rel="stylesheet" href="../assets/css/rapor-ranking.css?v=1">
<div id="page-content-wrapper" class="rapor-workspace rapor-ranking-page"><nav class="navbar top-navbar px-4 py-3"><h5 class="fw-bold mb-0">Laporan peringkat rapor</h5></nav><main class="container-fluid p-3 p-md-4 rapor-content">
<div class="rapor-intro"><div><h1><i class="fa-solid fa-ranking-star rapor-title-icon" aria-hidden="true"></i> Laporan peringkat siswa</h1><p><?= $selected?sanitize($selected['nama_kelas'].' / '.$tahun.' / '.$semester.' / '.$jenis):'Pilih kelas dan periode untuk melihat peringkat berdasarkan rata-rata nilai rapor.' ?></p></div><div class="rapor-ranking-actions"><a class="btn btn-outline-secondary" href="rapor.php?<?= sanitize(http_build_query($context)) ?>"><i class="fa-solid fa-arrow-left" aria-hidden="true"></i> Kembali ke rapor</a><?php if($ranking): ?><button type="button" class="btn btn-primary" id="rapor-ranking-print"><i class="fa-solid fa-print" aria-hidden="true"></i> Cetak laporan</button><?php endif ?></div></div>
<?php if($error): ?><div class="alert alert-danger" role="alert"><?= sanitize($error) ?></div><?php endif ?>
<?php if(!$ready): ?><div class="alert alert-warning">Penyimpanan rapor belum tersedia.</div><?php endif ?>
<section class="card mb-4 rapor-ranking-filters"><div class="card-body"><h6>Kelas, periode, dan tampilan laporan</h6><form method="get" class="row g-3 align-items-end">
<div class="col-md-3"><label class="form-label" for="ranking-class">Kelas</label><select id="ranking-class" name="kelas_id" class="form-select" required><option value="">Pilih kelas</option><?php foreach($classes as $c): ?><option value="<?= (int)$c['id'] ?>" <?= (int)$c['id']===$kelas?'selected':'' ?>><?= sanitize($c['nama_kelas']) ?></option><?php endforeach ?></select></div>
<div class="col-md-2"><label class="form-label" for="ranking-year">Tahun ajaran</label><select id="ranking-year" name="tahun_ajaran" class="form-select" required><?php foreach(array_unique(array_merge($years,$tahun?[$tahun]:[])) as $year): ?><option <?= $year===$tahun?'selected':'' ?>><?= sanitize($year) ?></option><?php endforeach ?></select></div>
<?php foreach(['semester'=>['Ganjil','Genap'],'jenis'=>['UTS','UAS']] as $key=>$values): ?><div class="col-md-2"><label class="form-label" for="ranking-<?= $key ?>"><?= $key==='jenis'?'Jenis rapor':'Semester' ?></label><select id="ranking-<?= $key ?>" name="<?= $key ?>" class="form-select"><?php foreach($values as $value): ?><option <?= ($key==='jenis'?$jenis:$semester)===$value?'selected':'' ?>><?= $value ?></option><?php endforeach ?></select></div><?php endforeach ?>
<div class="col-md-3"><label class="form-label" for="ranking-view">Tampilkan</label><select id="ranking-view" name="tampilan" class="form-select"><option value="top10" <?= !$all?'selected':'' ?>>Peringkat 1–10</option><option value="semua" <?= $all?'selected':'' ?>>Seluruh siswa</option></select></div>
<div class="col-12"><button class="btn btn-primary"><i class="fa-solid fa-magnifying-glass" aria-hidden="true"></i> Tampilkan laporan</button></div></form></div></section>
<?php if($ranking): ?>
<div class="rapor-stats"><div><strong><?= $ranking['total_siswa'] ?></strong><span>Peserta kelas dan arsip rapor kelas ini</span></div><div><strong><?= $ranking['layak'] ?></strong><span>Siswa dapat diperingkat</span></div><div><strong><?= count($excluded) ?></strong><span>Perlu pemeriksaan nilai / mapel</span></div></div>
<?php if(!$ranking['mapel_seragam']): ?><div class="alert alert-warning" role="status">Peringkat belum ditetapkan karena susunan mata pelajaran antar siswa belum sama atau ada mapel ganda. Periksa rapor siswa pada daftar di bawah.</div><?php elseif($ranking['sementara']): ?><div class="alert alert-warning" role="status"><strong>Peringkat sementara.</strong> Sebagian siswa belum memiliki rapor atau nilai lengkap. Peringkat akan dihitung ulang saat data tersimpan berubah.</div><?php endif ?>
<p class="rapor-note">Rata-rata = jumlah nilai akhir mata pelajaran dibagi jumlah mapel. Rata-rata dibulatkan dua angka desimal; nilai yang sama mendapat peringkat sama (contoh: 1, 2, 2, 4). Seluruh siswa yang seri pada peringkat 10 ikut ditampilkan. Eskul dan kehadiran tidak menambah nilai peringkat.</p>
<section class="card mb-4" data-rapor-filter><div class="card-body"><h6><i class="fa-solid fa-ranking-star" aria-hidden="true"></i> <?= $all?'Seluruh siswa':'Peringkat 1–10' ?><?= $ranking['sementara']?' — sementara':'' ?></h6><?php rapor_filter_toolbar('ranking-student-search','Cari siswa pada laporan',false); ?>
<?php if(!$shown): ?><p>Belum ada siswa yang dapat ditampilkan pada pilihan ini.</p><?php else: ?>
<div class="table-responsive"><table class="table align-middle rapor-ranking-table"><thead><tr><th>Peringkat</th><th>Nama siswa</th><th>Mapel</th><th>Total nilai</th><th>Rata-rata</th><th class="rapor-ranking-link">Rapor</th></tr></thead><tbody>
<?php foreach($shown as $entry): ?><tr data-filter-row data-filter-search-value="<?= sanitize($entry['nama_siswa']) ?>"><td><span class="rapor-ranking-number"><?= $entry['peringkat']??'—' ?></span></td><td><strong><?= sanitize($entry['nama_siswa']) ?></strong><?php if($entry['masalah']): ?><small class="d-block text-muted"><?= sanitize(implode(' ',$entry['masalah'])) ?></small><?php endif ?></td><td><?= $entry['nilai_lengkap'] ?>/<?= $entry['jumlah_mapel'] ?></td><td><?= $entry['total']!==null?number_format($entry['total'],2,',','.'): '—' ?></td><td><strong><?= $entry['rata_rata']!==null?number_format($entry['rata_rata'],2,',','.'): '—' ?></strong></td><td class="rapor-ranking-link"><?php if($entry['id']): ?><a class="btn btn-outline-secondary btn-sm" href="rapor.php?id=<?= $entry['id'] ?>">Buka rapor</a><?php else: ?>Belum tersimpan<?php endif ?></td></tr><?php endforeach ?>
</tbody></table></div><?php endif ?></div></section>
<?php if($excluded&&!$all): ?><details class="card rapor-fold rapor-ranking-excluded"><summary><i class="fa-solid fa-circle-exclamation" aria-hidden="true"></i> <?= count($excluded) ?> siswa belum dapat diperingkat <i class="fa-solid fa-chevron-down rapor-chevron" aria-hidden="true"></i></summary><div class="card-body"><div class="table-responsive"><table class="table"><thead><tr><th>Siswa</th><th>Perlu diperbaiki</th></tr></thead><tbody><?php foreach($excluded as $entry): ?><tr><td><?= sanitize($entry['nama_siswa']) ?></td><td><?= sanitize(implode(' ',$entry['masalah'])) ?></td></tr><?php endforeach ?></tbody></table></div></div></details><?php endif ?>
<?php endif ?></main></div><script src="../assets/js/rapor-table-tools.js?v=1" defer></script><script src="../assets/js/rapor-ranking.js?v=1" defer></script><?php require __DIR__.'/footer.php'; ?>
